let panel='list',lastKey=null,selectionAnimation=null;const motions=new WeakMap();
const $=s=>document.querySelector(s),reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function animatePanel(){if(reduced())return;const node=$('.case-file');if(node&&!node.hidden&&panel!=='map')node.animate([{opacity:0,transform:'translateY(16px) rotate(-.4deg)'},{opacity:1,transform:'translateY(0) rotate(0)'}],{duration:330,easing:'cubic-bezier(.2,.75,.25,1)'});}
function alignPanel(){const workspace=$('.case-workspace'),node=$('.case-file'),map=$('#outdoorMap')?.hidden?$('#indoorMap'):$('#outdoorMap');if(!workspace||!node||!map||$('#boardPage').hidden)return;const top=map.getBoundingClientRect().top-workspace.getBoundingClientRect().top-workspace.clientTop+12;node.style.top=Math.max(0,Math.round(top))+'px';}
function applyPanel(en=false,selected=false){const workspace=$('.case-workspace');workspace.dataset.explorerPanel=panel;$('#exploreList').setAttribute('aria-pressed',panel!=='map');$('#exploreMap').setAttribute('aria-pressed',panel==='map');$('#exploreList').textContent=selected?(en?'Place file':'地点档案'):($('#boardPage').dataset.section==='saved'?(en?'Saved clues':'收藏线索'):(en?'Trending clues':'热门线索'));}
export function showExplorerList(){panel='list';$('.case-workspace').dataset.explorerPanel=panel;$('#exploreList')?.setAttribute('aria-pressed','true');$('#exploreMap')?.setAttribute('aria-pressed','false');animatePanel();}
export function setupExplorer({en,onPeriod,onReset}){
 const t=(zh,eng)=>en?eng:zh,workspace=$('.case-workspace');$('#boardPage').classList.add('unified-explorer');document.body.classList.add('clue-explorer-enabled');window.addEventListener('resize',alignPanel);
 const bar=document.createElement('div');bar.className='explorer-toolbar';bar.innerHTML=`<div class="explorer-search-row"><div id="sharedSearchSlot"></div><div id="sharedOriginSlot"></div></div><div class="explorer-view-row"><div class="explorer-switch" role="group" aria-label="${t('工作台视图','Workspace view')}"><button id="exploreList" aria-pressed="true">${t('热门线索','Trending clues')}</button><button id="exploreMap" aria-pressed="false">${t('完整地图','Full map')}</button></div><label id="periodLabel">${t('回看','Look back')}<select id="popularPeriod" aria-label="${t('热门时间范围','Trending time period')}"><option value="7">${t('近7天','Last 7 days')}</option><option value="30">${t('近30天','Last 30 days')}</option></select></label><span id="explorerContext"></span><button id="explorerReset" class="text-button" hidden>← ${t('返回探索','Back to explore')}</button></div><div id="sharedFilterSlot"></div>`;
 workspace.prepend(bar);$('#sharedSearchSlot').append($('#searchForm'));$('#sharedOriginSlot').append($('.origin-row'));$('#sharedFilterSlot').append($('.categories'),$('#filters'));
 const hint=document.createElement('div');hint.id='mapClickHint';hint.className='map-click-hint';hint.textContent=t('点图钉选地点，再点击“前往这里”。','Pick a pin, choose a place, then go.');$('.evidence-board').prepend(hint);
 $('#exploreList').onclick=()=>{panel='list';applyPanel(en,!!$('#boardPage').classList.contains('has-case'));animatePanel();};$('#exploreMap').onclick=()=>{panel='map';applyPanel(en,!!$('#boardPage').classList.contains('has-case'));if(!reduced())$('.evidence-board').animate([{opacity:.7},{opacity:1}],{duration:280});};$('#popularPeriod').onchange=e=>{onPeriod(e.target.value);showExplorerList();};$('#explorerReset').onclick=onReset;
 $('#search').addEventListener('input',showExplorerList);$('#searchForm').addEventListener('submit',showExplorerList);document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',showExplorerList));
}
export function refreshExplorer({en,view,place,guide,stage,period,popular,query,category}){
 const t=(zh,eng)=>en?eng:zh,key=view+'/'+(place?.id||'')+'/'+(guide?stage:'');
 if(key!==lastKey){panel=place?'detail':'list';lastKey=key;animatePanel();}
 const workspace=$('.case-workspace');workspace.dataset.explorerSelected=place?'true':'false';workspace.dataset.explorerView=view;workspace.dataset.guideStage=guide?String(stage):'';
 $('#periodLabel').hidden=!popular||!!place;$('#popularPeriod').value=period;$('.explorer-search-row').hidden=!!place;$('#sharedFilterSlot').hidden=!!place;$('#explorerReset').hidden=!place;
 $('#explorerContext').textContent=place?nameOf(place,en):view==='saved'?t('留给下一次探索的线索','Clues kept for next time'):popular?t('热度为演示数据','Illustrative popularity'):query?t('搜索结果与地图联动','Search results, connected to the map'):category==='toilet'?t('按参考位置查找设施','Facilities around the reference origin'):t('在同一张地图上继续探索','Keep exploring on the same map');
 $('#results').classList.toggle('popular-results',popular);applyPanel(en,!!place);$('#boardPage').classList.remove('mobile-map-open');alignPanel();
}
const nameOf=(p,en)=>en?p.name:p.zh;
export function traceSelection({place,building,en=false,source='list'}){
 selectionAnimation?.cancel();$('.flying-clue')?.remove();if(reduced())return;
 const card=source==='map'?null:document.querySelector(`[data-place="${place.id}"]`),pin=document.querySelector(`[data-building="${building.id}"]`),map=$('#campusMap');if(!map)return;
 const a=(card||pin||map).getBoundingClientRect(),b=(pin||map).getBoundingClientRect(),ghost=document.createElement('div');ghost.className='flying-clue';ghost.textContent=en?'CLUE SELECTED':'线索已选定';ghost.setAttribute('aria-hidden','true');document.body.append(ghost);
 ghost.style.left=(a.x+a.width/2)+'px';ghost.style.top=(a.y+Math.min(a.height/2,35))+'px';selectionAnimation=ghost.animate([{opacity:0,transform:'translate(-50%,-50%) scale(.8) rotate(-6deg)'},{opacity:1,offset:.25,transform:'translate(-50%,-60%) scale(1) rotate(-3deg)'},{opacity:0,transform:`translate(calc(-50% + ${b.x+b.width/2-a.x-a.width/2}px),calc(-50% + ${b.y+b.height/2-a.y-Math.min(a.height/2,35)}px)) scale(.5) rotate(4deg)`}],{duration:650,easing:'cubic-bezier(.2,.65,.2,1)'});selectionAnimation.onfinish=()=>ghost.remove();selectionAnimation.oncancel=()=>ghost.remove();
}
export function stopMapTween(svg){const id=motions.get(svg);if(id)cancelAnimationFrame(id);motions.delete(svg);}
export function tweenMap(svg,target,commit){stopMapTween(svg);if(reduced()){commit(target);return;}const from=svg.getAttribute('viewBox').split(/\s+/).map(Number),start=performance.now();function tick(now){const progress=Math.min(1,(now-start)/500),e=1-(1-progress)**3;commit(from.map((v,i)=>v+(target[i]-v)*e));if(progress<1)motions.set(svg,requestAnimationFrame(tick));else motions.delete(svg);}motions.set(svg,requestAnimationFrame(tick));}
export function animateMapStage(inside){const el=inside?$('#indoorMap'):$('#outdoorMap');if(!reduced())el.animate([{opacity:.2,transform:inside?'translateY(16px) scale(.98)':'scale(1.025)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:420,easing:'cubic-bezier(.2,.7,.3,1)'});}
